def _config_route_gate_batch(pack_path, pack, v, history, mode, base,
                             events, queries, limit):
    # Batched hotload with a per-event routing-impact gate (config op
    # 17): [17, m, b, E, Q, L]. m is 0 (read-only preview) or 1 (atomic
    # commit); b the caller-observed base version; E a non-empty array
    # of non-decreasing-clock [e, t, p] events exactly like op 16's; Q a
    # non-empty list of distinct [s, d] pairs whose endpoints must both
    # be nodes of the h[b] topology; L a non-boolean integer in
    # 0..MAX_COST, the largest allowed single-routing cost increase.
    #
    # Every input validates first (shapes in the command entry; the h[b]
    # endpoint check, clocks, and event t/p here), then simulation walks
    # from h[b] in E order. An event whose t/p equals the previous state
    # is idempotent (row status 1, no version, an empty impact). Every
    # other event is a candidate: for each distinct query source the
    # route subcommand's lowest-cost paths with the deterministic
    # code-point tie break are computed before and after the event, and
    # each Q pair yields, in Q order, an impact row
    # [s, d, oldCost, newCost, oldPath, newPath, pass] with null cost and
    # [] path for an unreachable side (an endpoint absent from either
    # topology counts as unreachable). A pair passes when its old route
    # was unreachable, or the new route is reachable and
    # newCost-oldCost <= L; an event passes only when every pair passes
    # (row status 0, a candidate version). At the first failing
    # non-idempotent event simulation stops at once and the whole batch
    # rejects: batch status 2, old/new both the pre-call v, applied
    # false, config the pre-call pack, and PACK untouched in either mode.
    #
    # Once every event is a gated candidate, version/history append,
    # duplicate-resend recognition, the preview/commit difference, and
    # the single atomic replace follow op 16 exactly. O(BK(V^2+A) + S)
    # time and O(S + BRV + KV) extra space: B events, K distinct query
    # sources (K <= R queries), R queries, V nodes, A links, and S the
    # total input/output size (each impact path is at most V nodes).
    if base > v:
        fail(5)
    base_node_set = set(history[base][1]["nodes"])
    for s, d in queries:
        if s not in base_node_set or d not in base_node_set:
            fail(5)
    last_e = None
    for item in events:
        e = item[0]
        if last_e is not None and e < last_e:
            fail(5)
        last_e = e
        _validate_topology(item[1], metrics=True)
        if not _is_policy(item[2]):
            fail(5)

    # Routes on the running topology, one Dijkstra per distinct Q source,
    # handed from each passing event's after-side to the next event's
    # before-side. The h[b] routes seed the first event.
    cur_version = base
    cur_t = history[base][1]
    cur_p = history[base][2]
    cur_node_set = base_node_set
    cur_cost = {}
    cur_path = {}
    distinct_sources = []
    for s, _d in queries:
        if s not in cur_cost:
            cur_cost[s], cur_path[s] = shortest_paths(
                cur_t["nodes"], cur_t["links"], s)
            distinct_sources.append(s)

    rows = []
    suffix = []
    for event in events:
        e, new_t, new_p = event
        if new_t == cur_t and new_p == cur_p:
            rows.append([e, 1, cur_version, cur_version, []])
            continue
        if cur_version >= MAX_COST:
            fail(5)
        new_node_set = set(new_t["nodes"])
        new_cost = {}
        new_path = {}
        for s in distinct_sources:
            if s in new_node_set:
                new_cost[s], new_path[s] = shortest_paths(
                    new_t["nodes"], new_t["links"], s)
        impact = []
        passed = True
        for s, d in queries:
            if s not in cur_node_set or d not in cur_node_set:
                old_cost, old_path = None, []
            else:
                old_cost = cur_cost[s][d]
                old_path = cur_path[s][d] if old_cost is not None else []
            if s not in new_node_set or d not in new_node_set:
                n_cost, n_path = None, []
            else:
                n_cost = new_cost[s][d]
                n_path = new_path[s][d] if n_cost is not None else []
            if old_cost is None:
                pair_pass = True
            else:
                pair_pass = (n_cost is not None
                             and n_cost - old_cost <= limit)
            if not pair_pass:
                passed = False
            impact.append([s, d, old_cost, n_cost, old_path, n_path,
                           pair_pass])
        next_version = cur_version + 1
        if not passed:
            rows.append([e, 2, cur_version, cur_version, impact])
            return {"op": 17, "mode": mode, "status": 2, "old": v,
                    "new": v, "applied": False, "events": rows,
                    "config": pack}
        rows.append([e, 0, cur_version, next_version, impact])
        suffix.append([next_version, new_t, new_p])
        cur_version = next_version
        cur_t, cur_p = new_t, new_p
        cur_node_set = new_node_set
        cur_cost, cur_path = new_cost, new_path
    change_count = len(suffix)

    if base != v:
        # The only tolerated stale base is an exact resend: PACK must
        # already end exactly at the simulated suffix with every entry
        # equal; anything else is a version/suffix conflict.
        if change_count == 0 or v != base + change_count:
            fail(5)
        for offset, entry in enumerate(suffix, start=1):
            if history[base + offset] != entry:
                fail(5)
        return {"op": 17, "mode": mode, "status": 1, "old": base,
                "new": v, "applied": False, "events": rows,
                "config": pack}

    if change_count == 0:
        # All events idempotent at the current version: nothing to
        # append, so a commit writes nothing either.
        return {"op": 17, "mode": mode, "status": 0, "old": base,
                "new": base, "applied": False, "events": rows,
                "config": pack}
    new_pack = {"v": v + change_count, "t": cur_t, "p": cur_p,
                "h": history + suffix}

def shortest_paths(nodes, links, source):
    # Directed adjacency over up links only.
    adj = {n: [] for n in nodes}
    for link in links:
        if link["up"]:
            adj[link["from"]].append((link["to"], link["cost"]))

    cost_of = {n: None for n in nodes}
    path_of = {n: None for n in nodes}
    cost_of[source] = 0
    path_of[source] = [source]
    settled = set()

    # Dijkstra with O(V^2) selection. All link costs are >= 1, so every
    # predecessor of a lowest-cost path has a strictly smaller cost and is
    # settled before the node itself; hence only costs are compared during
    # selection, and full path sequences only during relaxation ties.
    while True:
        u = None
        ucost = None
        for n in nodes:
            c = cost_of[n]
            if c is not None and n not in settled and (ucost is None or c < ucost):
                u = n
                ucost = c
        if u is None:
            break
        settled.add(u)
        upath = path_of[u]
        for to, w in adj[u]:
            if to in settled:
                continue
            nc = ucost + w
            cc = cost_of[to]
            if cc is None or nc < cc:
                cost_of[to] = nc
                path_of[to] = upath + [to]
            elif nc == cc:
                cand = upath + [to]
                if cand < path_of[to]:
                    path_of[to] = cand
    return cost_of, path_of


def compute_routes(nodes, links, source):
    cost_of, path_of = shortest_paths(nodes, links, source)

    routes = []
    for n in sorted(nodes):
        if n == source:
            routes.append({"destination": n, "nextHop": source, "cost": 0,
                           "path": [source]})
        elif cost_of[n] is None:
            routes.append({"destination": n, "nextHop": None, "cost": None,
                           "path": []})
        else:
            p = path_of[n]
            routes.append({"destination": n, "nextHop": p[1],
                           "cost": cost_of[n], "path": p})
    return {"source": source, "routes": routes}


def compute_metric(nodes, links, source, order_names):
    # Directed adjacency over up links only.
    adj = {n: [] for n in nodes}
    for link in links:
        if link["up"]:
            adj[link["from"]].append(
                (link["to"], link["cost"], link["bandwidth"], link["latency"]))

    # Enumerate every directed simple path from the source via DFS and keep
    # the best one per destination under the ORDER metric hierarchy. Ties on
    # every metric go to the path with the smallest Unicode code point order.
    # best[n] = (comparison_key, (hop, cost, bandwidth, latency), path)
    best = {}

    def metric_key(hop_count, cost, bandwidth, latency):
        m = {"hop": hop_count, "cost": cost, "bandwidth": bandwidth,
             "latency": latency}
        # bandwidth prefers the larger value; the others the smaller.
        return tuple(-m[name] if name == "bandwidth" else m[name]
                     for name in order_names)

    def consider(path, hop_count, cost, bandwidth, latency):
        key = metric_key(hop_count, cost, bandwidth, latency)
        dest = path[-1]
        cur = best.get(dest)
        if cur is None or key < cur[0] or (key == cur[0] and path < cur[2]):
            best[dest] = (key, (hop_count, cost, bandwidth, latency),
                          list(path))

    # Iterative DFS with an explicit stack, so the enumeration depth is
    # bounded by heap, not by the Python recursion limit. metrics[d] holds
    # the accumulated (hop, cost, bandwidth, latency) for path[:d+1].
    path = [source]
    visited = {source}
    metrics = [(0, 0, MAX_COST, 0)]
    consider(path, 0, 0, MAX_COST, 0)
    stack = [iter(adj[source])]
    while stack:
        try:
            to, w, bw, lat = next(stack[-1])
        except StopIteration:
            stack.pop()
            if stack:
                metrics.pop()
                visited.remove(path.pop())
            continue
        if to in visited:
            continue
        visited.add(to)
        path.append(to)
        hop_count, cost, bandwidth, latency = metrics[-1]
        entry = (hop_count + 1, cost + w, min(bandwidth, bw), latency + lat)
        metrics.append(entry)
        consider(path, *entry)
        stack.append(iter(adj[to]))

    routes = []
    for n in sorted(nodes):
        if n == source:
            routes.append({"destination": n, "nextHop": source, "hopCount": 0,
                           "cost": 0, "bandwidth": None, "latency": 0,
                           "path": [source]})
        elif n not in best:
            routes.append({"destination": n, "nextHop": None, "hopCount": None,
                           "cost": None, "bandwidth": None, "latency": None,
                           "path": []})
        else:
            _, (hop_count, cost, bandwidth, latency), path = best[n]
            routes.append({"destination": n, "nextHop": path[1],
                           "hopCount": hop_count, "cost": cost,
                           "bandwidth": bandwidth, "latency": latency,
                           "path": path})
    return {"source": source, "order": order_names, "routes": routes}


def compute_wm(nodes, links, source, weights):
    # Directed adjacency over up links only.
    adj = {n: [] for n in nodes}
    for link in links:
        if link["up"]:
            adj[link["from"]].append(
                (link["to"], link["cost"], link["bandwidth"], link["latency"]))

    a, b, c, d = weights

    # Enumerate every directed simple path from the source via DFS (same
    # enumeration as compute_metric) and keep, per destination, the path
    # minimizing q = a*h + b*x + c*(M-y) + d*z with exact integer
    # arithmetic, where h/x/y/z are the hop count, cost sum, bottleneck
    # bandwidth, and latency sum. Ties on q go to the path with the
    # smallest Unicode code point order.
    # best[n] = (q, (hop, cost, bandwidth, latency), path)
    best = {}

    def consider(path, hop_count, cost, bandwidth, latency):
        q = (a * hop_count + b * cost + c * (MAX_COST - bandwidth)
             + d * latency)
        dest = path[-1]
        cur = best.get(dest)
        if cur is None or q < cur[0] or (q == cur[0] and path < cur[2]):
            best[dest] = (q, (hop_count, cost, bandwidth, latency),
                          list(path))

    # Iterative DFS with an explicit stack, so the enumeration depth is
